/* A convex floor shape pulled up into a solid (pianos, round tables…): only the sides facing you are drawn. */
function prism(pts, z0, z1, c, o = {}) {
  const n = pts.length; const cx = pts.reduce((a, p) => a + p[0], 0) / n, cy = pts.reduce((a, p) => a + p[1], 0) / n; const faces = [];
  for (let i = 0; i < n; i++) {
    const p = pts[i], q = pts[(i + 1) % n]; let nx = q[1] - p[1], ny = -(q[0] - p[0]);
    if (nx * ((p[0] + q[0]) / 2 - cx) + ny * ((p[1] + q[1]) / 2 - cy) < 0) { nx = -nx; ny = -ny; }
    const len = Math.hypot(nx, ny) || 1; nx /= len; ny /= len; if (nx + ny <= 0.02) continue;
    faces.push({ d: (p[0] + q[0] + p[1] + q[1]) / 2, svg: poly([[p[0], p[1], z0], [q[0], q[1], z0], [q[0], q[1], z1], [p[0], p[1], z1]], tone(c, -0.05 - 0.22 * clamp((nx - ny + 1) / 2, 0, 1)), o.line === false ? '' : edge(c)) });
  }
  faces.sort((a, b) => a.d - b.d);
  return faces.map((f) => f.svg).join('') + poly(pts.map(([x, y]) => [x, y, z1]), o.t || tone(c, 0.13), o.line === false ? '' : edge(c));
}
const circlePts = (cx, cy, r, n = 16, a0 = 0) => Array.from({ length: n }, (_, i) => { const a = a0 + (i / n) * Math.PI * 2; return [cx + Math.cos(a) * r, cy + Math.sin(a) * r]; });
